+// Counterfactual only: exact old after-spawn status loop, including the
+// timeout branch. Its borrowed child stays owned by the control for reap.
+fn old_after_spawn_observation(child: &mut Running, context: &str) {
+    let started = Instant::now();
+    let deadline = started + Duration::from_secs(2);
+    let mut polls = 0;
+    let status = loop {
+        let poll_started = started.elapsed();
+        let observed = child.0.try_wait();
+        let poll_finished = started.elapsed();
+        polls += 1;
+        if let Some(status) = observed.unwrap_or_else(|error| {
+            panic!("cannot read updater fixture status: {context}; {error}")
+        }) {
+            break status;
+        }
+        if Instant::now() >= deadline {
+            let elapsed = started.elapsed();
+            // The child may exit while the parent is descheduled after the
+            // previous poll. Preserve that evidence without clearing failure.
+            let final_status = child.0.try_wait();
+            panic!(
+                "updater fixture did not exit: {context}; pid={} elapsed={elapsed:?} \
+                 polls={polls} last_poll={poll_started:?}..{poll_finished:?} \
+                 final_status={final_status:?} (diagnostic only; timeout still fails)",
+                child.0.id(),
+            );
+        }
+        // Polling bounds the child; it does not choose a cut or order writes.
+        std::thread::sleep(Duration::from_millis(5));
+    };
+    panic!("old helper control unexpectedly completed: {status}");
+}
+
+#[test]
+fn the_old_spawn_watchdog_times_out_while_the_output_gate_is_still_held() {
+    let _forking = forking();
+    let mut child = spawn("read gate; printf 'old-updater\\n'", Stdio::piped());
+    let stdout = child.0.stdout.take().unwrap();
+    let started = Instant::now();
+    // Empty injection schedule: the controller owns stdin but writes nothing.
+    // It retains that descriptor until finish cancels it. No timed release can
+    // race a late parent poll into an incidental timeout.
+    let gate = Gate::release_at(child.0.stdin.take().unwrap(), Vec::new(), started);
+    let context = "old-after-spawn-control; gate=held-with-zero-releases";
+    let outcome = catch_unwind(AssertUnwindSafe(|| {
+        old_after_spawn_observation(&mut child, context);
+    }));
+    let elapsed = started.elapsed();
+    // Gather evidence while the gate is STILL owned/open. Do not clear the
+    // original failure if a diagnostic observes something unexpected.
+    let still_pending = child.0.try_wait();
+    let flags = rustix::fs::fcntl_getfl(&stdout);
+    let sample = (|| -> io::Result<_> {
+        let flags = flags?;
+        rustix::fs::fcntl_setfl(&stdout, flags | rustix::fs::OFlags::NONBLOCK)?;
+        if !rustix::fs::fcntl_getfl(&stdout)?.contains(rustix::fs::OFlags::NONBLOCK) {
+            return Err(io::Error::other("control stdout remained blocking"));
+        }
+        let mut bytes = [0_u8; 128];
+        Ok(rustix::io::read(&stdout, &mut bytes).map(|count| bytes[..count].to_vec()))
+    })();
+    let restored = (|| -> io::Result<_> {
+        let flags = flags?;
+        rustix::fs::fcntl_setfl(&stdout, flags)?;
+        Ok(rustix::fs::fcntl_getfl(&stdout)?)
+    })();
+    // Cancel/join the descriptor controller before asserting ANY observation;
+    // retain every receipt, and explicitly reap the direct child on either
+    // outcome. The normal fixture's Running implementation is unchanged.
+    let releases = gate.finish();
+    reap(&mut child);
+    let panic = outcome.expect_err("the exact old helper must time out");
+    let panic = if let Some(message) = panic.downcast_ref::<String>() {
+        message.clone()
+    } else if let Some(message) = panic.downcast_ref::<&str>() {
+        (*message).to_owned()
+    } else {
+        panic!("counterfactual failed with an unrelated non-text panic");
+    };
+    eprintln!("old helper control: elapsed={elapsed:?} pending={still_pending:?} gate_cancelled_and_joined={} releases={releases:?} sample={sample:?} restored={restored:?} original_panic={panic}", releases.is_ok());
+    assert!(panic.starts_with(&format!("updater fixture did not exit: {context};")), "{panic}");
+    assert!(panic.contains("final_status=Ok(None)"), "{panic}");
+    assert!(panic.contains("(diagnostic only; timeout still fails)"), "{panic}");
+    assert!(panic.contains("elapsed=") && panic.contains("polls=") && panic.contains("last_poll="), "{panic}");
+    assert!(elapsed >= Duration::from_secs(2), "{elapsed:?}; {panic}");
+    assert!(still_pending.unwrap().is_none(), "child exited before gate cancellation; {panic}");
+    assert!(releases.unwrap().is_empty(), "the held gate must have ZERO writes");
+    assert!(matches!(sample.unwrap(), Err(rustix::io::Errno::AGAIN)), "output before release is invalid counterfactual evidence");
+    assert_eq!(restored.unwrap(), flags.unwrap(), "probe must restore descriptor flags exactly");
+}
